/// <summary>
/// Set fields dependent on item/site settings.
/// </summary>
public void metUpdateFromItemSiteSettings(
    InventDim                           _inventDim)
{
    InventTable inventTable = InventTable::findByProduct(this.Product);
    if(inventTable)
    {
        InventItemSalesSetup itemSiteSetup;
        
        if(_inventDim.inventSiteID)
        {
            itemSiteSetup = InventItemSalesSetup::find(
                inventTable.ItemID,
                inventDim::findOrCreate(_inventDim).inventDimId);
        }
        if(itemSiteSetup.METSalesUnit)
        {
            this.UoM = UnitOfMeasure::findBySymbol(itemSiteSetup.METSalesUnit).RecId;
        }
        else
        {
            this.UoM = UnitOfMeasure::findBySymbol(inventTable.inventTableModuleSales().UnitId).RecId;
        }
    }
}
